"""Native function schemas, no image-specific prompts or coordinates."""
from .diagnosis import CATEGORIES

def obj(properties,required=None):return {'type':'object','properties':properties,'required':list(properties) if required is None else required,'additionalProperties':False}
STRING={'type':'string'};IDS={'type':'array','items':STRING}
BOX={'type':'array','items':{'type':'number'},'minItems':4,'maxItems':4}
def tool(name,description,parameters):return {'type':'function','function':{'name':name,'description':description,'parameters':parameters}}
TPBOX=obj({k:{'type':'number'} for k in ('left','top','right','bottom')})
ARGUMENTS=obj({'world_matrix':{'type':'array','items':{'type':'number'},'minItems':6,'maxItems':6},'reference_ids':IDS,'mode':STRING,'target_tp':TPBOX,'measurement_viewport':TPBOX,'kind':{'type':'string','enum':['geometry','frame','text','formula','arrow']},'data':{'type':'object','additionalProperties':True},'source_crop':BOX,'representation':{'type':'string','enum':['raster','vector']},'backend':{'type':'string','enum':['vtracer','imagetracerjs','pixelruns']},'padding':{'type':'number'},'attributes':{'type':'object','additionalProperties':{'type':['string','number']}},'text':STRING,'parent_id':STRING,'svg':STRING},[])
ARGUMENTS['properties']['remove_background']={'type':'boolean','default':True,'description':'sp_photo defaults to local RMBG2 after original crop and before raster embedding/vectorization. Set false when the intended background is needed, or after visual inspection shows RMBG damages the subject and the original crop is complete and free of frame/neighbor contamination. Retain before/after evidence.'}
ARGUMENTS['description']='Method-specific arguments only. method and target_ids are siblings of args, never inside args. sp_replace requires kind, data, measurement_viewport, target_tp. bp_patch requires attributes (including d/points/style) or text; do not put attributes directly under args. bp_add requires parent_id and svg.'
ARGUMENTS['properties']['source_crop']={**BOX,'description':'Original-image pixel xywh independently located around the complete intended subject. Never copy current target_tp. Exclude every enclosing frame, neighboring label/object, and excess background; inspect original crop before use. Crop includes full subject; local RMBG2 removes background before embedding/vectorization. Inspect resulting alpha for missing subject or retained neighbors.'}
operation=obj({'method':{'type':'string','enum':['tp_transform','tp_align','tp_fit','sp_replace','sp_photo','bp_patch','bp_add','bp_remove']},'target_ids':IDS,'args':ARGUMENTS})
issue=obj({'id':STRING,'types':{'type':'array','items':{'type':'string','enum':list(CATEGORIES)},'minItems':1},'description':STRING,'original_evidence':STRING,'target_ids':IDS,'neighbor_ids':IDS,'operations':{'type':'array','items':operation}})
observation=obj({'id':STRING,'description':STRING,'original_evidence':STRING,'frame_ids':IDS,'target_ids':IDS,'neighbor_ids':IDS,'types':{'type':'array','items':{'type':'string','enum':list(CATEGORIES)},'minItems':1},'decision':{'type':'string','enum':['confirmed','dismissed','duplicate']},'duplicate_of':STRING},['id','description','original_evidence','frame_ids','target_ids','neighbor_ids','types','decision'])
TOOLS=[
 tool('inspect_regions','Locate objects by visible names and neighbor relationships first; then read current SVG objects and measured TP plus original/current enlarged crops. Predicted image boxes are not measured TP. Frame IDs refer to current snapshot. Explicit crop boxes are full image/world coordinates; nothing here modifies SVG.',obj({'frame_ids':IDS,'object_ids':IDS,'original_boxes':{'type':'array','items':BOX},'current_boxes':{'type':'array','items':BOX}},[])),
 tool('submit_diagnosis','First call: submit the complete deduplicated survey after baseline frame delivery. Later calls may amend existing confirmed observations or add new observations by supplying their complete records; prior observations remain. No SVG modification.',obj({'observations':{'type':'array','items':observation}})),
 tool('sample_original_colors','Local color sampling only when needed. regions are original-image pixel x,y,width,height. Reports modal and mean RGB; does not infer semantic color ownership.',obj({'regions':{'type':'array','items':BOX}})),
 tool('apply_repairs','Execute actual local TP/SP/BP. Classify each issue (multi types), select involved IDs and neighbors, state original evidence. Each issue is atomic; successful issues modify SVG. Tool returns measured results and refreshed images. Current SVG placement must use TP. Original-image source extraction must be independently located from the original subject, never copied or inferred from current TP.',obj({'issues':{'type':'array','items':issue,'minItems':1}})),
 tool('finish_review','Record a pending-verification checklist after seeing latest actual output images. In issue_results.evidence record actual actions, any fallback or cascading repair, target/container check and neighbor check. Account for original/global/local relationships. Leave unverified or remaining issues explicit; this does not establish human visual acceptance.',obj({'summary':STRING,'global_review':STRING,'issue_results':{'type':'array','items':obj({'issue_id':STRING,'status':{'type':'string','enum':['resolved','remaining','uncertain','false_positive']},'evidence':STRING})},'remaining_issues':IDS}))
]
